package net.flovex.core.scoreboard;
import net.flovex.core.FlovexCore;import net.flovex.core.util.ColorUtil;import org.bukkit.*;import org.bukkit.entity.Player;import org.bukkit.scoreboard.*;import java.time.LocalDate;import java.util.*;
public final class ScoreboardService{
 private final FlovexCore plugin;private int task;
 public ScoreboardService(FlovexCore p){plugin=p;}
 public void start(){if(!plugin.scoreboardConfig().getBoolean("enabled",true))return;task=Bukkit.getScheduler().scheduleSyncRepeatingTask(plugin,()->Bukkit.getOnlinePlayers().forEach(this::update),20,Math.max(20,plugin.scoreboardConfig().getInt("update-ticks",20)));}
 public void stop(){if(task!=0)Bukkit.getScheduler().cancelTask(task);}
 public void update(Player p){if(plugin.getStorage().preference(p.getUniqueId(),"scoreboard","true").equals("false"))return;var cfg=plugin.scoreboardConfig();Scoreboard b=Bukkit.getScoreboardManager().getNewScoreboard();Objective o=b.registerNewObjective("flovex","dummy",color(cfg.getString("styles."+plugin.getStorage().preference(p.getUniqueId(),"scoreboard-style","modern")+".title",cfg.getString("title","&b&lFLOVEX"))));o.setDisplaySlot(DisplaySlot.SIDEBAR);String style=plugin.getStorage().preference(p.getUniqueId(),"scoreboard-style","modern");String stylePath="styles."+style+".";List<String> lines=cfg.getStringList(stylePath+"lines");if(lines.isEmpty())lines=cfg.getStringList("lines");int score=lines.size();Set<String> used=new HashSet<>();for(String raw:lines){String line=raw.replace("%rank%",plugin.getRanks().getDisplayPrefix(p)).replace("%player%",p.getName()).replace("%money%",plugin.getEconomy().format(plugin.getEconomy().balance(p.getUniqueId()))).replace("%shards%",String.format(Locale.US,"%,d",plugin.getShardShop().balance(p.getUniqueId()))).replace("%team%",team(p)).replace("%kills%",String.valueOf(p.getStatistic(Statistic.PLAYER_KILLS))).replace("%deaths%",String.valueOf(p.getStatistic(Statistic.DEATHS))).replace("%ping%",String.valueOf(p.getPing())).replace("%date%",LocalDate.now().toString()).replace("%playtime%",String.format("%dh",p.getStatistic(Statistic.PLAY_ONE_MINUTE)/72000));try{if(Bukkit.getPluginManager().isPluginEnabled("PlaceholderAPI"))line=(String)Class.forName("me.clip.placeholderapi.PlaceholderAPI").getMethod("setPlaceholders",Player.class,String.class).invoke(null,p,line);}catch(Throwable ignored){}line=color(line);while(!used.add(line))line=line+"§"+(score%10);o.getScore(line).setScore(score--);}p.setScoreboard(b);}
 public void toggle(Player p){boolean show=plugin.getStorage().preference(p.getUniqueId(),"scoreboard","true").equals("false");plugin.getStorage().setPreference(p.getUniqueId(),"scoreboard",String.valueOf(show));if(show)update(p);else p.setScoreboard(Bukkit.getScoreboardManager().getNewScoreboard());}
 private String team(Player p){var rows=plugin.getStorage().rows("SELECT t.name FROM teams t JOIN team_members m ON m.team_id=t.id WHERE m.uuid=?",p.getUniqueId().toString());return rows.isEmpty()?"None":String.valueOf(rows.getFirst().get("name"));}
 private String color(String s){return ColorUtil.color(s);}
}